//! Test-only utilities shared by the integration tests.
//!
//! The crucial piece is [`oracle`]: a **third, independently written**
//! evaluator that computes the expected result straight from the JSON fixture
//! rows with literal nested loops and hand-coded SQL NULL semantics. It does
//! NOT import any production execution code (`exec`, `query::rewrite`, …) —
//! only JSON types. The production system's answers are compared against this
//! oracle, so the reference answers are not generated by the code under test.

// Each integration-test binary compiles this shared module on its own and
// exercises only a subset of the helpers; unused-in-one-binary items are not
// dead code across the suite.
#![allow(dead_code)]

use decorrelate::api::service::{handle, Outcome};
use decorrelate::api::types::QueryRequest;
use decorrelate::catalog::Catalog;
use serde_json::{json, Map, Value};
use std::collections::HashMap;

/// Expected outcome of one subquery over all outer rows.
#[derive(Debug, Clone, PartialEq)]
pub enum OracleOutcome {
    /// One JSON value per outer row (JSON null = SQL NULL).
    Values(Vec<Value>),
    /// Both evaluators must fail at this outer row with this category/code.
    Error { at_outer_row: usize, category: &'static str, code: &'static str },
}

/// Evaluate one subquery spec (the same JSON shape the HTTP API accepts)
/// directly against raw JSON rows.
pub fn evaluate(
    outer_rows: &[Map<String, Value>],
    inner_rows: &[Map<String, Value>],
    spec: &Map<String, Value>,
) -> OracleOutcome {
    let kind = spec.get("type").and_then(Value::as_str).unwrap_or("");
    let correlations = spec
        .get("correlations")
        .and_then(Value::as_array)
        .expect("spec must have correlations array");

    let mut out = Vec::with_capacity(outer_rows.len());
    for (row_idx, outer) in outer_rows.iter().enumerate() {
        // Literal nested-loop correlation with hand-coded SQL equality.
        let mut matched: Vec<&Map<String, Value>> = Vec::new();
        for inner in inner_rows {
            let mut all_true = true;
            for c in correlations {
                let oname = c["outer"]["name"].as_str().unwrap();
                let iname = c["inner"]["name"].as_str().unwrap();
                let ov = outer.get(oname).unwrap_or(&Value::Null);
                let iv = inner.get(iname).unwrap_or(&Value::Null);
                if !sql_equal(ov, iv) {
                    all_true = false;
                    break;
                }
            }
            if all_true {
                matched.push(inner);
            }
        }

        match reduce(kind, spec, &matched) {
            Ok(v) => out.push(v),
            Err((category, code)) => {
                return OracleOutcome::Error { at_outer_row: row_idx, category, code };
            }
        }
    }
    OracleOutcome::Values(out)
}

/// SQL equality: NULL never equals anything (not even NULL).
fn sql_equal(a: &Value, b: &Value) -> bool {
    if a.is_null() || b.is_null() {
        return false;
    }
    // Strict typed equality: no implicit Int/Float coercion (matches service).
    std::mem::discriminant(a) == std::mem::discriminant(b) && a == b
}

fn reduce(
    kind: &str,
    spec: &Map<String, Value>,
    matched: &[&Map<String, Value>],
) -> Result<Value, (&'static str, &'static str)> {
    match kind {
        "exists" => Ok(Value::Bool(!matched.is_empty())),
        "not_exists" => Ok(Value::Bool(matched.is_empty())),
        "scalar" => {
            if matched.len() > 1 {
                return Err(("CardinalityViolation", "cardinality_violation"));
            }
            let col = spec["value"]["name"].as_str().unwrap();
            Ok(matched.first().map(|r| r.get(col).cloned().unwrap_or(Value::Null)).unwrap_or(Value::Null))
        }
        "scalar_agg" => {
            let func = spec.get("agg_func").and_then(Value::as_str).unwrap_or("");
            match func {
                "count" => match spec.get("agg_argument") {
                    None => Ok(json_i64(matched.len() as i64)),
                    Some(arg) => {
                        let col = arg["name"].as_str().unwrap();
                        let n = matched.iter().filter(|r| !r.get(col).unwrap_or(&Value::Null).is_null()).count();
                        Ok(json_i64(n as i64))
                    }
                },
                "sum" => {
                    let col = spec["agg_argument"]["name"].as_str().unwrap();
                    let mut acc: Option<f64> = None;
                    let mut is_int = true;
                    for r in matched {
                        match r.get(col).unwrap_or(&Value::Null) {
                            Value::Number(n) => {
                                if n.as_i64().is_none() {
                                    is_int = false;
                                }
                                let f = n.as_f64().unwrap();
                                acc = Some(acc.unwrap_or(0.0) + f);
                            }
                            Value::Null => {}
                            _ => return Err(("TypeMismatch", "sum_non_numeric")),
                        }
                    }
                    match acc {
                        None => Ok(Value::Null),
                        Some(f) if is_int && is_i64_exact(f) => Ok(json_i64(f as i64)),
                        Some(f) => serde_json::Number::from_f64(f)
                            .map(Value::Number)
                            .ok_or(("Internal", "bad_float")),
                    }
                }
                _ => Err(("Validation", "agg_func_required")),
            }
        }
        "not_in" => Err(("UnsupportedNotIn", "not_in_unsupported")),
        _ => Err(("Validation", "unknown_kind")),
    }
}

fn json_i64(i: i64) -> Value {
    Value::Number(serde_json::Number::from(i))
}

fn is_i64_exact(f: f64) -> bool {
    f.is_finite() && f >= i64::MIN as f64 && f <= i64::MAX as f64 && f.fract() == 0.0
}

// ───────────────────────────── request helpers ─────────────────────────────

/// Catalog loaded from the shipped fixtures (CWD is the crate root under cargo).
pub fn fixture_catalog() -> Catalog {
    Catalog::load_from_dir("fixtures/tables").expect("fixture catalog loads")
}

/// Run the full orchestration service on a JSON request, using the fixture
/// catalog, and return its typed outcome.
pub fn run(value: Value) -> Outcome {
    let request: QueryRequest = serde_json::from_value(value).expect("request JSON must deserialize");
    handle(request, "test-request".to_string(), &fixture_catalog())
}

/// Build an inline relation JSON object.
pub fn relation(name: &str, schema: Value, rows: Value) -> Value {
    json!({ "name": name, "schema": schema, "rows": rows })
}

/// Convenience constructor for the two-column Int64 schemas used everywhere.
pub fn kv_schema(outer_col: &str, inner_col: &str) -> Value {
    json!([
        { "name": outer_col, "type": "Int64" },
        { "name": inner_col, "type": "Int64" }
    ])
}

/// Int64 key plus Utf8 tag — the common outer-relation shape.
pub fn key_tag_schema(key: &str, tag: &str) -> Value {
    json!([
        { "name": key, "type": "Int64" },
        { "name": tag, "type": "Utf8" }
    ])
}

pub fn correlation(outer: &str, inner: &str) -> Value {
    json!({ "outer": { "name": outer }, "inner": { "name": inner } })
}

/// Full request with an inline outer relation and inline inner relations.
pub fn request(
    outer_name: &str,
    outer_schema: Value,
    outer_rows: Value,
    relations: Vec<Value>,
    subqueries: Vec<Value>,
) -> Value {
    json!({
        "request_id": "oracle-check",
        "outer": relation(outer_name, outer_schema, outer_rows),
        "relations": relations,
        "subqueries": subqueries,
    })
}

// ──────────────────────────── outcome extractors ───────────────────────────

pub fn success(outcome: &Outcome) -> decorrelate::api::types::QueryResponse {
    match outcome {
        Outcome::Success(r) => r.clone(),
        other => panic!("expected success, got: {}", variant(other)),
    }
}

pub fn rejected(outcome: &Outcome) -> (u16, decorrelate::api::types::ErrorResponse) {
    match outcome {
        Outcome::Rejected { status, response } => (*status, response.clone()),
        other => panic!("expected rejection, got: {}", variant(other)),
    }
}

pub fn verified_error(outcome: &Outcome) -> (u16, decorrelate::api::types::ErrorResponse) {
    match outcome {
        Outcome::VerifiedError { status, response, results: _ } => (*status, response.clone()),
        other => panic!("expected verified error, got: {}", variant(other)),
    }
}

fn variant(o: &Outcome) -> &'static str {
    match o {
        Outcome::Success(_) => "Success",
        Outcome::VerifiedError { .. } => "VerifiedError",
        Outcome::Rejected { .. } => "Rejected",
    }
}

/// Appended result columns of the decorrelated strategy as plain JSON values.
pub fn appended_columns(
    resp: &decorrelate::api::types::QueryResponse,
) -> HashMap<String, Vec<Value>> {
    resp.results
        .decorrelated
        .columns
        .iter()
        .map(|c| (c.name.clone(), c.values.clone()))
        .collect()
}

/// Assert the two strategies' views agree (the service already guarantees
/// this; tests assert on the returned flag and contents explicitly).
pub fn assert_strategies_agree(resp: &decorrelate::api::types::QueryResponse) {
    assert!(resp.results.equivalent, "service reports strategies non-equivalent");
    assert_eq!(resp.results.naive.status, "ok");
    assert_eq!(resp.results.decorrelated.status, "ok");
    assert_eq!(
        serde_json::to_value(&resp.results.naive.columns).unwrap(),
        serde_json::to_value(&resp.results.decorrelated.columns).unwrap(),
        "naive/decorrelated appended columns differ"
    );
}

/// Pull raw JSON rows back out of a relation JSON object for the oracle.
pub fn rows_of(rel: &Value) -> Vec<Map<String, Value>> {
    rel.get("rows")
        .and_then(Value::as_array)
        .unwrap()
        .iter()
        .map(|v| v.as_object().unwrap().clone())
        .collect()
}
